<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserGroupMembership\Domain\Gateway;

use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\UserGroupMembership;

class UserGroupMembershipCursor
{
    public function __construct(
        private int $limit,
        private ?string $sinceUid = null,
    ) {
    }
    public function next(UserGroupMembership $userGroupMembership, ?int $size): UserGroupMembershipCursor
    {
        $next = clone $this;
        $next->sinceUid = $userGroupMembership->uid();
        $next->limit = $size ?? $this->limit;
        return $next;
    }
    public function limit(): int
    {
        return $this->limit;
    }
    public function sinceUid(): ?string
    {
        return $this->sinceUid;
    }
}
